            ld (fs_res), hl
            ld hl, fs_delete
            jp fs_go
			ret			; end of #asm

fn_filesystem_open:		; function open (asm keyword), FileSystem.cls line 175
            pop hl
            ld (fs_a1), hl
            pop hl
            ld e, (hl)
            inc hl
