fn_filesystem_close:		; function close (asm keyword), FileSystem.cls line 191
            pop hl
            ld e, (hl)
            inc hl
            ld d, (hl)
            ld (fs_a1), de
            pop hl
            ld (fs_res), hl
            ld hl, fs_closeh
